-- Adiciona um campo dedicado pro detalhamento do objeto (texto longo,
-- separado do "objeto" curto que ja fica em classe) -- pedido pra
-- enriquecer o relatorio que vai pro cliente (Souza Cruz).
alter table public.processos
  add column if not exists detalhamento_objeto text;

-- Preenche/atualiza a partir de uma segunda exportacao do LegalDesk (BDR),
-- com o texto de Detalhamento do Objeto por processo. Mesmo padrao das
-- outras importacoes: casa por CNJ (so digitos), e quando a planilha tem
-- valor ele prevalece (COALESCE(novo, atual)).
DO $$
DECLARE
  _atualizados int;
  _nao_encontrados text;
BEGIN
  CREATE TEMP TABLE _detalhamento_objeto_bdr (
    cnj_digits text,
    detalhe text
  ) ON COMMIT DROP;


  UPDATE public.processos p
  SET detalhamento_objeto = COALESCE(d.detalhe, p.detalhamento_objeto)
  FROM _detalhamento_objeto_bdr d
  WHERE regexp_replace(p.numero_cnj, '\D', '', 'g') = d.cnj_digits;

  GET DIAGNOSTICS _atualizados = ROW_COUNT;

  SELECT string_agg(d.cnj_digits, ', ')
  INTO _nao_encontrados
  FROM _detalhamento_objeto_bdr d
  WHERE NOT EXISTS (
    SELECT 1 FROM public.processos p
    WHERE regexp_replace(p.numero_cnj, '\D', '', 'g') = d.cnj_digits
  );

  RAISE NOTICE 'Processos atualizados: %', _atualizados;
  IF _nao_encontrados IS NOT NULL THEN
    RAISE NOTICE 'CNJs da planilha que nao bateram com nenhum processo cadastrado: %', _nao_encontrados;
  END IF;
END $$;
